import sys

def solve_sudoku(board):
    changed = True
    while changed:
        changed = False
        for i in range(4):
            seen = {}
            for j in range(4):
                if board[i][j] != 0:
                    if board[i][j] in seen:
                        seen[board[i][j]] += 1
                    else:
                        seen[board[i][j]] = 1
            zeros = [j for j in range(4) if board[i][j] == 0]
            if len(zeros) <= 2:
                missing = [x for x in [1, 2, 3, 4] if x not in seen]
                if len(missing) == len(zeros):
                    for idx, j in enumerate(zeros):
                        if board[i][j] == 0:
                            board[i][j] = missing[idx]
                            changed = True

        for j in range(4):
            seen = {}
            for i in range(4):
                if board[i][j] != 0:
                    if board[i][j] in seen:
                        seen[board[i][j]] += 1
                    else:
                        seen[board[i][j]] = 1
            zeros = [i for i in range(4) if board[i][j] == 0]
            if len(zeros) <= 2:
                missing = [x for x in [1, 2, 3, 4] if x not in seen]
                if len(missing) == len(zeros):
                    for idx, i in enumerate(zeros):
                        if board[i][j] == 0:
                            board[i][j] = missing[idx]
                            changed = True

    return board

def main():
    board = []
    for _ in range(4):
        line = sys.stdin.readline().strip()
        row = list(map(int, line.split()))
        board.append(row)

    board = solve_sudoku(board)

    for row in board:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
